create table wksp_dtesc.sgt_evento_subtarea (
    id                  number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    evento_accion_id    number not null enable,
    subtarea            varchar2(255 byte) not null enable,
    resultado           varchar2(20 byte) default 'PENDIENTE' not null enable,
    detalle             varchar2(1000 byte),
    tiempo_empleado_min number,
    fecha_ejecucion     timestamp(6) default systimestamp not null enable,
    ejecutado_por       varchar2(255 byte) not null enable,
    secuencia           number default 1 not null enable,
    creado_por          varchar2(255 byte),
    creado_el           timestamp(6) default systimestamp
);

alter table wksp_dtesc.sgt_evento_subtarea
    add constraint chk_sgt_evento_subtarea_resultado
        check ( resultado in ( 'PENDIENTE', 'EXITOSO', 'FALLIDO', 'PARCIAL', 'NO_APLICA' ) ) enable;

alter table wksp_dtesc.sgt_evento_subtarea
    add constraint pk_sgt_evento_subtarea primary key ( id )
        using index enable;

alter table wksp_dtesc.sgt_evento_subtarea
    add constraint uq_sgt_evento_subtarea_seq unique ( evento_accion_id,
                                                       secuencia )
        using index enable;


